(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"PSA_001_001_006_WORBS_READER_DRAFT_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/PSA_001_001_006_WORBS_READER_DRAFT_20261017.md","sourceSha256":"2e67ce17704c8276b87a4ad8e5f96d65134e471684eca5b07e78ff565aa7260e","passage":{"book":"psa","chapter":1,"v1":1,"v2":6,"ref":"시편 1:1–6"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"두 길의 문턱에서: 말씀에 뿌리내린 사람","overview":["시편 1편은 삶이 언제나 두 부류로 명쾌하게 갈라진다고 주장하는 단순한 성공 격언이 아닙니다. 이 시는 사람이 누구의 말을 듣고 무엇을 즐거워하며 어떤 길을 자기 길로 삼는지를 묻습니다. 복 있는 사람의 중심에는 성취가 아니라 여호와의 가르침이 있고, 의인과 악인의 마지막 차이는 눈앞의 번영보다 여호와께서 그 길을 아시는가에 달려 있습니다. 말씀을 가까이하는 사람은 물길 곁에 심긴 나무에, 그 말씀을 거절하는 사람은 바람에 날리는 겨에 비유됩니다. 이 두 이미지 사이에서 시인은 인생의 방향, 지속성, 심판, 그리고 하나님과의 관계를 한 편의 시로 압축합니다."],"centralMessage":"표제 없이 시작하는 이 지혜시는 시편 전체의 입구에 놓여 있습니다. 이어지는 시편 2편이 열방과 기름부음 받은 왕의 문제를 다룬다면, 시편 1편은 먼저 그 왕의 통치 아래 살아갈 사람이 어떤 길을 택하는지를 묻습니다. 따라서 두 시는 하나님의 가르침과 하나님의 왕권이라는 서로 다른 입구를 열면서도, 결국 같은 질문—누구에게 삶을 맡길 것인가—으로 만납니다.","literaryStructure":[{"v1":1,"v2":2,"title":"듣는 자리와 서는 자리가 바뀌는 순간"},{"v1":3,"v2":3,"title":"물길 곁에 옮겨 심긴 나무"},{"v1":4,"v2":5,"title":"물을 잃은 겨와 서지 못하는 사람"},{"v1":6,"v2":6,"title":"두 길의 마지막을 아시는 여호와"}],"sections":[{"id":"psa1-1-2","v1":1,"v2":2,"title":"듣는 자리와 서는 자리가 바뀌는 순간","paragraphs":["첫 단어 **אַשְׁרֵי**(아슈레이)는 한 사람에게 앞으로 복을 주겠다는 명령이나 약속이라기보다, 이미 참된 복의 자리에 있는 삶을 감탄하며 가리키는 말입니다. ‘복되다’라는 선언이 문장 맨 앞에 놓이기 때문에 독자는 그 복이 무엇으로 결정되는지 뒤따르는 묘사를 읽으며 알아가게 됩니다. ‘그 사람’이라는 단수형은 특정 역사적 인물만을 지칭하기보다 누구에게나 열려 있는 전형적 인물상을 세웁니다. 이 말은 축복 행위를 나타내는 다른 히브리어 표현과도 구별되며, 여기서는 하나님 앞에서 바르게 놓인 삶의 상태를 드러냅니다.","1절의 세 동사 ‘걷다–서다–앉다’는 세 종류의 행동을 기계적으로 분류하지 않습니다. 조언을 받아 움직이고, 어떤 길을 생활의 방식으로 삼고, 마침내 어떤 모임의 자리에 머무는 모습을 점층적으로 그립니다. ‘악인–죄인–오만한 자’ 역시 서로 완전히 다른 세 계급이 아니라 하나님의 길을 거스르는 삶의 여러 얼굴입니다. 특히 ‘오만한 자’는 단순히 농담하는 사람이 아니라 하나님의 지혜와 책망을 비웃는 태도를 나타냅니다. 이 병행법을 반드시 모든 타락이 같은 세 단계를 거친다는 심리 법칙으로 읽을 필요는 없습니다. 시적 반복의 핵심은 사람이 듣는 말, 걸어가는 길, 머무는 자리가 결국 서로 분리되지 않는다는 데 있습니다.","2절의 **כִּי אִם**(키 임, ‘오히려/도리어’)은 금지의 연속을 뒤집습니다. 복 있는 사람은 세상에서 물러나 아무것도 하지 않는 사람이 아닙니다. 그의 내면을 채우는 적극적 즐거움이 있습니다. **תּוֹרָה**(토라)는 좁은 의미의 법조문만이 아니라 여호와께서 주시는 가르침과 삶의 지침을 가리킵니다. ‘즐거워한다’는 말은 외부에서 강요된 의무가 아니라 마음의 기울어짐을 나타냅니다. 이어지는 **יֶהְגֶּה**(예헤게, ‘되뇌다/읊조리다’)는 조용한 생각만이 아니라 말씀을 낮은 소리로 반복하여 입과 마음에 머물게 하는 행위를 떠올리게 합니다. ‘낮과 밤’은 하루 두 차례의 의식을 규정하기보다 생활의 모든 시간에 스며드는 지속성을 표현합니다. 신명기 6:6–9의 말씀 기억과도 이 지점에서 공명합니다.","따라서 첫 두 절의 대조는 ‘나쁜 일을 하지 않는 사람’과 ‘좋은 일을 하는 사람’의 도덕 목록보다 깊습니다. 악인의 조언이 사람의 걸음을 빚듯, 여호와의 가르침도 사람의 욕망과 판단과 언어를 빚습니다. 문제는 무엇을 얼마나 많이 아느냐보다 무엇이 그 사람 안에서 계속 말하고 있느냐입니다."]},{"id":"psa1-3-3","v1":3,"v2":3,"title":"물길 곁에 옮겨 심긴 나무","paragraphs":["시인은 복 있는 사람을 물길 곁에 심긴 나무에 비유합니다. **שָׁתוּל**(샤툴)은 그 자리에 우연히 자란 나무보다는 의도적으로 심거나 옮겨 심은 나무를 연상시킵니다. **פַּלְגֵי מָיִם**(팔게 마임)은 여러 갈래의 물길을 가리켜, 나무가 계절의 우연한 소나기에만 의존하지 않는 모습을 강조합니다. 고대 농경 환경에서 안정적인 물 공급은 생존과 결실의 중요한 조건이었습니다. 그러나 비유의 관심은 관개 기술 자체가 아니라 보이지 않는 근원이 눈에 보이는 생명력을 지탱한다는 사실에 있습니다.","‘때를 따라 열매를 맺는다’는 말은 늘 열매가 달려 있다는 뜻이 아닙니다. 나무의 결실에는 **그때**가 있습니다. 잎이 시들지 않는다는 이미지와 무엇을 하든 형통하리라는 마지막 진술을 합쳐도, 모든 의인이 언제나 부유하고 병들지 않는다는 보증은 나오지 않습니다. 시편 안에는 고난받는 의인의 탄식이 이어지고(시 13편), 악인의 형통을 보고 괴로워하는 기도도 있습니다(시 73편). 시편 1편의 ‘형통’은 그런 현실을 지우는 계산식이 아니라 여호와의 가르침에 뿌리내린 삶이 궁극적으로 헛되이 소멸하지 않는다는 지혜의 전망입니다.","이 나무는 예레미야 17:7–8의 물가에 뿌리내린 나무와 가까운 상을 이루고, 창세기의 동산과 생명 이미지도 멀리서 환기합니다. 그렇지만 시편 1편이 에덴의 특정 나무를 직접 가리킨다고 단정할 필요는 없습니다. 공통된 시적 논리는 생명이 스스로의 힘만으로 유지되지 않는다는 데 있습니다."]},{"id":"psa1-4-5","v1":4,"v2":5,"title":"물을 잃은 겨와 서지 못하는 사람","paragraphs":["4절은 단호하게 시작합니다. ‘악인들은 그렇지 않다.’ 앞선 세 절의 풍성한 묘사가 이 짧은 부정으로 뒤집힙니다. 나무가 뿌리와 물길을 통해 한곳에 머문다면, **מֹץ**(모츠, ‘겨’)는 타작 뒤 바람에 흩어지는 가벼운 껍질입니다. 두 이미지의 핵심 대조는 단순한 무게 차이가 아니라 지속성과 소멸, 뿌리내림과 흩어짐입니다. 악인이 당장 세상에서 아무 힘도 없다는 말은 아닙니다. 그는 한때 큰 힘을 가진 듯 보일 수 있지만, 시는 그 힘이 최종 심판 앞에서 무엇을 지탱할 수 있는지 묻습니다.","5절의 ‘심판에 서지 못한다’는 말은 법정에 물리적으로 출석하지 못한다는 뜻보다 판정 앞에서 정당함을 인정받지 못한다는 뜻에 가깝습니다. ‘의인들의 모임’은 단순한 친목 모임이 아니라 하나님 앞에 속한 공동체의 정체성을 환기합니다. 여기서 심판을 오직 어느 한 역사적 사건으로 제한하거나, 반대로 마지막 날의 장면만으로 좁힐 필요는 없습니다. 이 시는 하나님의 판정이 삶의 실상을 드러낸다는 확신을 말하고, 정경 전체의 독자는 그 확신이 최종 심판의 지평으로 열려 있음을 함께 읽게 됩니다."]},{"id":"psa1-6-6","v1":6,"v2":6,"title":"두 길의 마지막을 아시는 여호와","paragraphs":["마지막 절에서 비유는 관계의 언어로 바뀝니다. **יוֹדֵעַ יְהוָה**(요데아 아도나이, ‘여호와께서 아신다’)의 ‘안다’는 단순한 정보 파악만을 뜻하지 않습니다. 여호와는 악인의 길도 모르시는 분이 아닙니다. 여기서 의인의 길을 아신다는 말은 그 길을 인정하고 돌보며 관계 안에 두신다는 뜻을 품습니다. 그 반대편에서는 ‘악인의 길이 망한다’고 말합니다. 흥미롭게도 마지막 문장은 의인과 악인 두 사람의 운명을 단순히 병렬하지 않고, **길 자체**를 대비합니다. 시의 처음에 등장했던 길이 끝에서 다시 돌아와 전체를 감쌉니다.","이 결론 때문에 시편 1편의 중심은 자기 수양의 비결보다 여호와와 맺는 관계에 있습니다. 복 있는 사람은 자신의 경건을 쌓아 스스로 안전해진 사람이 아니라, 하나님의 가르침을 즐거워하고 하나님께서 아시는 길을 걷는 사람입니다. 시편의 긴 탄식과 왕권의 노래를 읽기 전에, 독자는 그 모든 기도가 어느 길에서 시작되는지 먼저 듣습니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"문학적 위치와 시편 2편의 연결","paragraphs":["시편 1편은 ‘복 있는 사람’으로 열리고 시편 2편은 ‘그에게 피하는 사람은 복이 있다’는 말로 끝납니다(시 2:12). 이 **אַשְׁרֵי**의 반복은 두 시를 함께 읽도록 돕는 중요한 단서입니다. 시편 1편의 말씀 묵상과 시편 2편의 열방의 모의는 히브리어 **הגה** 계열의 동사를 공유하지만, 한쪽은 여호와의 가르침을 되뇌고 다른 쪽은 헛된 일을 꾀합니다. 같은 인간의 언어 능력이 전혀 다른 방향으로 사용되는 것입니다. 두 시의 결합은 편집적·정경적 독법에서 강한 설득력을 갖지만, 두 시가 반드시 처음부터 하나의 작품으로 쓰였다는 역사적 결론까지 강제하지는 않습니다."]},{"title":"지혜의 일반화와 의인의 고난","paragraphs":["시편 1편은 지혜 문학의 전형적 양극 대조를 사용합니다. 이 형식을 개인의 고난을 재단하는 판결문으로 바꾸면 시편 자체와 충돌합니다. 시편 37편과 73편, 욥기는 눈앞의 번영이 최종적인 의로움의 증거가 아님을 거듭 드러냅니다. 그러므로 ‘형통’은 고난의 부재가 아니라 여호와의 판단 속에서 삶의 길이 보존된다는 큰 지평 안에서 읽어야 합니다."]},{"title":"본문과 해석의 경계","paragraphs":["본문의 마소라 전승에서 핵심 대조를 뒤집는 중대한 이문을 전제로 할 필요는 없습니다. 더 중요한 해석상 갈림길은 ‘복’을 물질적 성공으로, ‘묵상’을 머릿속의 무언 반복으로, ‘안다’를 단순한 지식으로 축소할 것인가에 있습니다. 원어와 시적 평행 구조는 각각 그런 축소를 경계하게 합니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 시편 1:1–6 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"unfoldingWord Translation Notes · unfoldingWord · 시편 1장 서론 및 1:1–6, en_tn v91 · CC BY-SA 4","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 1:1–6, 기존 JudeBible 원어 자료 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 원문 사용: 히브리어 형태와 어절을 대조하고 한국어로 해설했으며, 앱의 어절 분리·재키잉 결과를 원판 그대로의 별도 판본이라고 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 1편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 1편의 복됨·토라·길·의인·악인·옮겨 심다 관련 표제어, 로컬 한국어 뜻풀이 검토자료 대조 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 표제어의 기본 뜻을 한국어로 현지화한 기존 검토자료를 참고했으며, 문맥 해설은 별도로 작성했습니다. 이 기록은 앱 구현·배포 승인에 관한 주장이 아닙니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 1:1–6 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 지혜시의 위치, 복의 언어, 나무와 겨의 대비, 정경적 연결에 관한 설명을 참고하여 한국어로 새롭게 구성·확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 1장 서론 및 1:1–6, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 병행법·시적 이미지·번역상 의미 구분을 참고해 한국어 설명을 재서술·확장했습니다. 원자료의 unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.","연구 및 재서술 안내\n이 글은 시편 1:1–6의 히브리어 본문을 직접 읽고, 위에 명시한 원어 자료와 두 주석 자료의 해당 대목을 실제 확인한 뒤 작성한 한국어 WORBS 연구 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료)와 개별 본문 해설 참고자료(Tyndale·unfoldingWord)를 구별했습니다. 연속적인 한국어 성경 번역문이나 원 주석의 긴 번역문을 옮기지 않았으며, 참고한 주제와 표현의 해석적 관계를 위에 밝혔습니다. 이 글 전체가 독립 저작물인지 특정 자료의 파생 저작물인지에 대한 법적 판단은 여기서 확정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이고, 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes의 확인된 이용조건은 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)이며, 저작권자 표시·변경 고지와 해당 조건을 별도로 따라야 합니다. 출처 표시는 다른 성경 판본이나 제3자 자료의 재배포 허가를 대신하지 않습니다. 이 원고 전체에 적용될 단일 라이선스는 별도의 권리 검토 전에 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 1:1–6, 기존 JudeBible 원어 자료 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 원문 사용: 히브리어 형태와 어절을 대조하고 한국어로 해설했으며, 앱의 어절 분리·재키잉 결과를 원판 그대로의 별도 판본이라고 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 1편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 1편의 복됨·토라·길·의인·악인·옮겨 심다 관련 표제어, 로컬 한국어 뜻풀이 검토자료 대조 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 표제어의 기본 뜻을 한국어로 현지화한 기존 검토자료를 참고했으며, 문맥 해설은 별도로 작성했습니다. 이 기록은 앱 구현·배포 승인에 관한 주장이 아닙니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 1:1–6 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 지혜시의 위치, 복의 언어, 나무와 겨의 대비, 정경적 연결에 관한 설명을 참고하여 한국어로 새롭게 구성·확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 1장 서론 및 1:1–6, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 병행법·시적 이미지·번역상 의미 구분을 참고해 한국어 설명을 재서술·확장했습니다. 원자료의 unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.\n\n연구 및 재서술 안내\n이 글은 시편 1:1–6의 히브리어 본문을 직접 읽고, 위에 명시한 원어 자료와 두 주석 자료의 해당 대목을 실제 확인한 뒤 작성한 한국어 WORBS 연구 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료)와 개별 본문 해설 참고자료(Tyndale·unfoldingWord)를 구별했습니다. 연속적인 한국어 성경 번역문이나 원 주석의 긴 번역문을 옮기지 않았으며, 참고한 주제와 표현의 해석적 관계를 위에 밝혔습니다. 이 글 전체가 독립 저작물인지 특정 자료의 파생 저작물인지에 대한 법적 판단은 여기서 확정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon의 확인된 이용조건은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)이고, 기반 WLC 본문은 Public Domain으로 식별됩니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes의 확인된 이용조건은 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)이며, 저작권자 표시·변경 고지와 해당 조건을 별도로 따라야 합니다. 출처 표시는 다른 성경 판본이나 제3자 자료의 재배포 허가를 대신하지 않습니다. 이 원고 전체에 적용될 단일 라이선스는 별도의 권리 검토 전에 확정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"PSA_002_001_012_WORBS_READER_DRAFT_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/PSA_002_001_012_WORBS_READER_DRAFT_20261017.md","sourceSha256":"d6c6743140b65a166b795735b2bb71b2be7d913a4876d79362eaca91fc3fc74c","passage":{"book":"psa","chapter":2,"v1":1,"v2":12,"ref":"시편 2:1–12"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"헛된 모의와 시온의 왕: 열방 앞에 선 하나님의 통치","overview":["시편 2편은 세계의 왕들이 여호와와 그가 세우신 왕에게 저항하는 장면에서 시작하지만, 결말은 그들에게 멸망을 선고하는 데서 멈추지 않습니다. 시는 반역하는 왕들에게 지혜를 얻고 여호와를 섬기며 그분의 통치 아래 피하라고 권합니다. 땅의 소란과 하늘의 평정, 반역자들의 말과 여호와의 선언, 시온의 왕이 전하는 칙령과 열방에 주어지는 권고가 차례로 교차합니다. 중심 논지는 인간 권력이 하나님의 통치를 폐기할 수 없으며, 하나님이 세우신 왕권을 인정하는 것이 열방의 지혜라는 데 있습니다."],"centralMessage":"이 작품은 왕의 즉위와 다윗 왕조의 언약을 배경으로 이해할 수 있는 왕권시입니다. 그러나 어느 특정 왕의 어느 즉위식에서 처음 불렸는지는 본문만으로 확정하기 어렵습니다. 시는 역사적 다윗 왕조의 왕권 언어를 사용하면서 그 왕권이 감당해야 할 세계적 과제를 펼칩니다. 정경 속에서는 시편 1편의 ‘복 있는 사람’이 시편 2편 끝의 ‘피하는 사람은 복이 있다’와 맞닿고, 하나님의 가르침을 받아들이는 개인의 길과 하나님의 왕권에 응답하는 열방의 길이 하나의 서론을 이룹니다.","literaryStructure":[{"v1":1,"v2":3,"title":"열방이 함께 말하지만 그 말은 헛되다"},{"v1":4,"v2":6,"title":"하늘의 웃음과 시온의 선언"},{"v1":7,"v2":9,"title":"‘너는 내 아들’이라는 왕권의 칙령"},{"v1":10,"v2":12,"title":"왕들에게 다시 주어진 선택"}],"sections":[{"id":"psa2-1-3","v1":1,"v2":3,"title":"열방이 함께 말하지만 그 말은 헛되다","paragraphs":["첫 절의 ‘어찌하여’는 상황을 몰라서 묻는 질문이 아닙니다. 시인은 열방의 소란을 바라보며 그 계획의 어리석음을 드러내는 수사적 질문을 던집니다. ‘민족들이 소란을 피우다’에 해당하는 히브리어 동사는 집단적인 동요를 나타내고, ‘백성들이 헛된 일을 꾀하다’의 **יֶהְגּוּ**(예헤구)는 시편 1:2에서 여호와의 가르침을 되뇌는 **יֶהְגֶּה**(예헤게)와 같은 어근에 속합니다. 앞의 시에서 사람은 하나님의 가르침을 입에 머금었지만, 여기서 열방은 헛된 계획을 입에 올립니다. 시편 1–2편을 나란히 읽으면 ‘무엇을 되뇌는가’라는 문제가 개인의 마음에서 국제 정치의 언어로 확장됩니다.","2절은 추상적인 민족의 소란을 ‘땅의 왕들’과 ‘통치자들’의 결집으로 구체화합니다. 그들의 대적은 여호와와 그의 **מְשִׁיחוֹ**(메시호, ‘그가 기름부으신 자’)입니다. 이 단어의 일차적인 역사적 지평은 여호와께서 세우신 왕, 특히 다윗 왕조의 통치자입니다. 이를 본문의 역사적 장면에서 지우고 처음부터 예수라는 이름만 대입하면, 왜 열방의 왕들이 시온의 왕에게 저항하는지라는 시의 정치적·언약적 긴장이 사라집니다. 반대로 이 단어를 단지 고대 왕의 직함으로만 닫아 두면 정경 안에서 왕권 약속이 어떻게 확대되는지도 놓칩니다.","3절에서 반역자들은 하나님의 통치를 ‘결박’과 ‘줄’에 비유합니다. 그들은 여호와의 질서와 기름부음 받은 왕의 통치를 자신들을 묶는 속박으로 경험합니다. 이 말은 시인의 판단이 아니라 **반역자들이 자기 입으로 제시하는 해석**입니다. 본문은 왕들의 정치적 불만을 기록하면서도 그 불만이 곧 정당한 진단이라고 인정하지 않습니다. ‘끊어 버리자’와 ‘벗어 던지자’는 평행 구문은 공동 행동의 의지를 증폭시키지만, 1절은 그 모의가 처음부터 ‘헛됨’을 품고 있음을 독자에게 알려 주었습니다."]},{"id":"psa2-4-6","v1":4,"v2":6,"title":"하늘의 웃음과 시온의 선언","paragraphs":["장면은 땅에서 하늘로 급격히 바뀝니다. 1–3절에서 왕들은 분주하게 모여 말하지만, 4절에서 여호와는 하늘에 ‘앉아’ 계십니다. 앉아 계신다는 표현은 무관심이나 부재가 아니라 흔들리지 않는 왕좌의 이미지를 만듭니다. 여호와의 웃음과 비웃음은 고통받는 사람을 조롱하는 성격 묘사가 아닙니다. 자기 힘으로 하나님의 주권을 무너뜨릴 수 있다고 생각하는 권력의 허망함을 드러내는 시적 표현입니다. 이 반전은 ‘누가 실제로 왕좌를 차지하고 있는가’라는 질문에 대한 시의 답입니다.","5절에서는 웃음이 말씀으로 바뀝니다. 여호와는 분노 가운데 말씀하시며 반역자들을 놀라게 하십니다. ‘그때’라는 시간의 전환은 하나님의 응답이 단순한 방관이 아님을 밝힙니다. 그러나 하나님의 결정적인 말씀은 예상과 다르게 전쟁의 세부 계획이 아닙니다. 6절의 핵심은 ‘내가 내 왕을 세웠다’는 선언입니다. 히브리어 **נָסַכְתִּי**(나사크티)는 이 문맥에서 왕을 세우거나 즉위시키는 의미로 이해되지만, 동사의 기본 어휘 관계와 표현 방식에는 논의가 있습니다. 어느 하나의 어원 설명을 곧바로 역사적 즉위 의식의 정확한 절차로 확정할 수는 없습니다. 분명한 것은 왕의 권위가 스스로의 무력이나 열방의 승인에서 나오지 않고 여호와의 주도적 행위에서 나온다는 점입니다.","왕이 세워진 곳은 ‘나의 거룩한 산 시온’입니다. 시온은 단순한 지도 좌표가 아니라 여호와의 임재와 다윗 왕권이 만나는 신학적 공간입니다. 하늘에 좌정하신 하나님이 땅의 시온에 왕을 세우셨다는 공간적 병치는 하나님 통치와 인간 왕권을 동일시하지 않으면서도 연결합니다. 왕은 하나님을 대신해 독자적인 신적 존재가 되는 것이 아니라 하나님의 통치를 대표하도록 부름받습니다."]},{"id":"psa2-7-9","v1":7,"v2":9,"title":"‘너는 내 아들’이라는 왕권의 칙령","paragraphs":["7절부터 발화자가 바뀝니다. 이제 시온의 왕이 여호와께서 자신에게 하신 말씀을 전합니다. ‘내가 여호와의 칙령을 선포하리라’는 문장은 왕의 통치가 개인적 야망이 아니라 받은 말씀에 근거함을 보여 줍니다. ‘너는 내 아들이다. 내가 오늘 너를 낳았다’는 선언은 고대 왕권 언어 속에서 읽어야 합니다. 여기서 ‘오늘’은 왕권이 공적으로 선포되는 시점과 밀접하게 연결되며, ‘아들’은 하나님과 왕의 언약적 관계를 나타냅니다. 사무엘하 7:14의 ‘나는 그에게 아버지가 되고 그는 내게 아들이 되리라’는 약속과 시편 89:26–27의 왕권 언어가 중요한 배경입니다. 이를 고대 왕이 생물학적으로 신에게서 태어났다는 진술로 읽는 것은 이스라엘의 언약적 왕권 이해를 흐립니다.","8절에서 여호와는 왕에게 열방을 ‘유산’으로, 땅끝을 ‘소유’로 주겠다고 하십니다. 땅끝은 특정 국경의 확정된 측량선이 아니라 통치 범위의 보편성을 나타내는 시적 극대화입니다. 역사 속 다윗 왕조의 어느 왕도 이 전망을 온전히 실현했다고 말하기 어렵습니다. 따라서 이 약속은 실제 왕정의 언어로 시작하지만 그 왕정의 한계를 넘어서는 기대를 남깁니다. 시편의 정경적 독법은 바로 이 미완의 기대를 주목합니다.","9절의 ‘철장’과 ‘질그릇’은 통치의 힘과 저항의 취약함을 대비합니다. 마소라 본문의 **תְּרֹעֵם**(테로엠)은 통상 ‘그들을 깨뜨리다’로 읽히며, 뒤따르는 질그릇을 부수는 이미지와 결합합니다. 반면 고대 그리스어 칠십인역 전승에는 ‘그들을 목양하다/다스리다’라는 동사로 읽힌 흐름이 있고, 요한계시록 2:27과 12:5, 19:15의 인용·암시는 이 전승과 관련됩니다. 이는 작은 표현 차이가 왕권의 성격을 해석하는 데 영향을 줄 수 있음을 보여 줍니다. 그렇다고 한쪽을 ‘폭력적인 구약’과 다른 쪽을 ‘온화한 신약’으로 분리해서는 안 됩니다. 두 전승 모두 왕의 권위가 반역하는 세력보다 우위에 있음을 말하며, 시편의 바로 다음 단락은 그들에게 돌아올 기회를 권합니다."]},{"id":"psa2-10-12","v1":10,"v2":12,"title":"왕들에게 다시 주어진 선택","paragraphs":["시의 마지막은 놀랍게도 열방의 왕들에게 직접 말을 건넵니다. ‘그러므로 이제’라는 전환 뒤에 ‘지혜를 얻으라’, ‘교훈을 받으라’는 명령이 이어집니다. 왕들이 앞에서 헛된 일을 꾀했다면 이제는 지혜를 배워야 합니다. 이 권고는 단순한 항복 명령 이상입니다. 세계를 다스린다고 여기는 이들이 먼저 자신이 가르침을 받아야 하는 존재임을 인정하라는 요구입니다. 시편 1편의 토라 지혜가 여기서 왕들에게도 요청됩니다.","11절은 ‘두려움으로 섬기라’와 ‘떨며 기뻐하라’를 나란히 놓습니다. 두려움과 기쁨은 상쇄되는 감정이 아닙니다. 하나님을 가볍게 다루지 않는 경외와 그분의 통치 안에서 발견되는 기쁨이 함께 요청됩니다. 시는 열방을 단지 제거해야 할 대상으로만 그리지 않고, 여호와께 합당하게 응답할 수 있는 청중으로 대합니다.","12절의 **נַשְּׁקוּ־בַר**(나슈쿠 바르)는 본문비평과 번역에서 특별히 주의해야 할 구절입니다. 마소라 본문을 따라 **בַּר**(바르)를 아람어계 ‘아들’로 읽으면 왕에게 충성을 표하는 ‘아들에게 입 맞추라’는 뜻이 됩니다. 이는 7절의 ‘내 아들’과 자연스럽게 이어지지만, 그곳의 히브리어 ‘아들’(**בֵּן**, 벤)과 여기의 단어가 다르다는 점은 설명이 필요합니다. 고대 그리스어 번역 전승은 이 대목을 ‘훈계를 붙들라’는 방향으로 읽습니다. 또 순수함 또는 순전한 경배와 관련해 이해하려는 해석도 전해집니다. 그러므로 ‘아들’이라는 독법은 중요한 전통이지만, 다른 고대 독법이 전혀 없었던 것처럼 단정해서는 안 됩니다. 어떤 독법을 취하든 앞선 문맥이 요구하는 바는 여호와의 왕권에 대한 반역을 버리고 합당하게 응답하라는 것입니다.","끝의 ‘그에게 피하는 사람은 모두 복이 있다’는 선언은 위협으로 가득한 듯했던 시의 방향을 다시 드러냅니다. 심판을 말하는 왕권시가 피난처의 언어로 닫힙니다. ‘그’가 누구를 가리키는지는 가까운 문맥의 왕과 궁극적 통치자 여호와 사이에서 논의될 수 있지만, 시 전체의 신학에서는 여호와의 보호와 그가 세우신 왕권이 분리되지 않습니다. 첫 시의 시작에 울렸던 **אַשְׁרֵי**(아슈레이)가 여기서 다시 울립니다. 시편의 문턱은 하나님의 말씀을 즐거워하는 사람과 하나님의 통치 아래 피하는 사람을 하나의 복된 길로 연결합니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"역사적 왕권과 정경적 메시아 독법","paragraphs":["시편 2편의 최초 역사적 지평은 다윗 왕조의 왕을 하나님의 아들로 선포하는 왕권 전통입니다. 사무엘하 7장과 시편 89편의 약속이 이 언어를 설명합니다. 그러나 시편의 후속 역사에는 왕권의 붕괴와 시온의 위기가 놓여 있습니다. 따라서 열방을 유업으로 받는 왕의 모습은 과거 왕정의 성공담으로 완결되지 않습니다. 사도행전 4:25–28은 이 시의 열방과 통치자들의 반역을 예수의 고난 사건에 적용하고, 사도행전 13:33과 히브리서 1:5는 ‘너는 내 아들’이라는 선언을 예수 그리스도와 연결합니다. 이것은 고대 왕권 언어를 지운 대체가 아니라 그 언어가 남긴 약속과 긴장을 정경 안에서 다시 읽는 방식입니다. 각 신약 본문이 왕권, 부활, 높임을 어떤 맥락에서 말하는지도 각각 구별해야 합니다."]},{"title":"폭력의 이미지와 회개의 초대","paragraphs":["9절만 떼어 내면 이 시를 무조건적인 제국 정복의 선언으로 오해하기 쉽습니다. 그러나 10–12절은 바로 그 왕들에게 교훈과 경외와 피난을 요청합니다. 철장과 질그릇의 비유는 하나님의 통치를 거스르는 권력이 끝내 절대적일 수 없다는 시적 판정입니다. 이를 현대 국가나 개인이 자신을 ‘시온의 왕’과 동일시하여 폭력을 정당화하는 면허로 사용하는 것은 본문이 설정한 왕권의 출처와 대상을 혼동하는 것입니다."]},{"title":"중요한 번역 갈림길","paragraphs":["2:9의 ‘깨뜨리다/목양하다’는 마소라 본문의 모음과 고대 그리스어 번역 전승 사이의 독법 차이를, 2:12의 ‘아들에게 입 맞추라/훈계를 붙들라’는 드문 어휘와 고대 역본 해석의 차이를 드러냅니다. 어느 쪽이든 원어의 불확실성을 숨기지 않으면서 시 전체의 화자 전환, 시온의 왕권, 열방을 향한 마지막 권고를 함께 살펴야 합니다. 특정 번역 선택 하나에 시편 전체의 기독론을 매달지 않는 것이 바람직합니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 시편 2:1–12 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"unfoldingWord Translation Notes · unfoldingWord · 시편 2장 서론 및 2:1–12, en_tn v91 · CC BY-SA 4","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 2:1–12, 기존 JudeBible 원어 자료 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 형태와 어절을 직접 대조하고 한국어로 문맥 해설을 작성했습니다. 앱의 어절 분리·재키잉을 원전 자체의 판본 변경으로 간주하지 않았습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 2편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 2편의 아들·길·복됨 등 관련 표제어, 로컬 한국어 뜻풀이 검토자료 대조 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 기본 뜻에 대한 한국어 현지화 검토자료를 참고하였으며, 2:12의 경쟁 독법은 별도로 구분했습니다. 이 사실만으로 앱의 실제 바인딩이나 배포 승인을 추정하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 2:1–12 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 왕권시의 구조, 즉위·언약 관계, 열방과 왕의 대조에 관한 설명을 참고하여 한국어로 재구성·확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 2장 서론 및 2:1–12, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 발화자 전환, 시적 병행법, ‘아들’과 왕권 표현의 번역상 주의를 참고하여 한국어로 재서술·확장했습니다. 원자료의 unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.\n* 칠십인역 시편의 고대 그리스어 번역 전승 · 고대 그리스어 성경 번역자들 · 시편 2:9, 2:12의 비교 독법 · 고대 원전 Public Domain(현대 교정판·웹사이트의 별도 저작권은 포함하지 않음)\n   * 대조에 실제 열람한 자료: https://www.studylight.org/interlinear-study-bible/hebrew/psalms/2-9.html\n   * 대조에 실제 열람한 자료: https://www.anselm-project.com/bible/crux/psalm-2-12-kiss-the-son\n   * 변경·번역 고지: 두 구절의 번역 전승 차이만 확인하여 한국어로 해설했으며, 현대 판본의 긴 원문이나 웹사이트의 해설을 재수록하지 않았습니다.","연구 및 재서술 안내\n이 글은 시편 2:1–12의 히브리어 본문을 직접 읽고, 위에 명시한 원어 자료와 본문별 참고 주석, 중요한 고대 번역 전승을 대조하여 작성한 한국어 WORBS 연구 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료·고대 역본 대조)와 개별 본문 해설 참고자료(Tyndale·unfoldingWord)를 구별했습니다. 참고자료의 논지를 그대로 순서대로 옮기지 않고 시의 화자 전환과 문학적 흐름을 중심으로 새롭게 서술했습니다. 참고·재서술·변형 관계는 위에 밝혔으며 이 원고 전체의 독립 저작물 또는 파생 저작물 해당 여부를 임의로 확정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC와 고대 그리스어 원전은 Public Domain으로 구별됩니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건을 가지므로 저작권자 지정 고지와 변경 표시, 적용 가능한 동일조건변경허락 의무를 별도로 검토해야 합니다. 현대 그리스어 교정판과 웹사이트의 편집·해설에 관한 권리는 고대 원전의 Public Domain 지위로 자동 소멸하지 않습니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전에 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 2:1–12, 기존 JudeBible 원어 자료 v2.2 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 형태와 어절을 직접 대조하고 한국어로 문맥 해설을 작성했습니다. 앱의 어절 분리·재키잉을 원전 자체의 판본 변경으로 간주하지 않았습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 2편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 2편의 아들·길·복됨 등 관련 표제어, 로컬 한국어 뜻풀이 검토자료 대조 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 기본 뜻에 대한 한국어 현지화 검토자료를 참고하였으며, 2:12의 경쟁 독법은 별도로 구분했습니다. 이 사실만으로 앱의 실제 바인딩이나 배포 승인을 추정하지 않습니다.\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 2:1–12 및 시편 1–2편 서론, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 왕권시의 구조, 즉위·언약 관계, 열방과 왕의 대조에 관한 설명을 참고하여 한국어로 재구성·확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 2장 서론 및 2:1–12, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 발화자 전환, 시적 병행법, ‘아들’과 왕권 표현의 번역상 주의를 참고하여 한국어로 재서술·확장했습니다. 원자료의 unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.\n* 칠십인역 시편의 고대 그리스어 번역 전승 · 고대 그리스어 성경 번역자들 · 시편 2:9, 2:12의 비교 독법 · 고대 원전 Public Domain(현대 교정판·웹사이트의 별도 저작권은 포함하지 않음)\n   * 대조에 실제 열람한 자료: https://www.studylight.org/interlinear-study-bible/hebrew/psalms/2-9.html\n   * 대조에 실제 열람한 자료: https://www.anselm-project.com/bible/crux/psalm-2-12-kiss-the-son\n   * 변경·번역 고지: 두 구절의 번역 전승 차이만 확인하여 한국어로 해설했으며, 현대 판본의 긴 원문이나 웹사이트의 해설을 재수록하지 않았습니다.\n\n연구 및 재서술 안내\n이 글은 시편 2:1–12의 히브리어 본문을 직접 읽고, 위에 명시한 원어 자료와 본문별 참고 주석, 중요한 고대 번역 전승을 대조하여 작성한 한국어 WORBS 연구 주석입니다. 공통 성경 원문 자료(OSHB·WLC·히브리어 어휘 자료·고대 역본 대조)와 개별 본문 해설 참고자료(Tyndale·unfoldingWord)를 구별했습니다. 참고자료의 논지를 그대로 순서대로 옮기지 않고 시의 화자 전환과 문학적 흐름을 중심으로 새롭게 서술했습니다. 참고·재서술·변형 관계는 위에 밝혔으며 이 원고 전체의 독립 저작물 또는 파생 저작물 해당 여부를 임의로 확정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC와 고대 그리스어 원전은 Public Domain으로 구별됩니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/) 조건을 가지므로 저작권자 지정 고지와 변경 표시, 적용 가능한 동일조건변경허락 의무를 별도로 검토해야 합니다. 현대 그리스어 교정판과 웹사이트의 편집·해설에 관한 권리는 고대 원전의 Public Domain 지위로 자동 소멸하지 않습니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전에 확정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"PSA_003_001_008_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/PSA_003_001_008_WORBS_READER_DRAFT_20261018.md","sourceSha256":"9ff3ef859bf89fa2b1b8a8fbff91a603d2084a35a80b6fcb6a58054697d4291a","passage":{"book":"psa","chapter":3,"v1":1,"v2":8,"ref":"시편 3:1–8"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"포위된 밤을 지나: 머리를 드시는 하나님","overview":["시편 3편은 하나님의 기름부음 받은 왕을 열방이 거스른다는 시편 2편의 거대한 장면을 한 사람의 절박한 밤으로 좁힙니다. 시편 2편에서는 하늘의 왕이 시온에 왕을 세우셨지만, 시편 3편의 기도자는 바로 그 하나님의 보호를 받지 못하는 것처럼 보입니다. 많은 사람이 그를 공격하고, 더 아프게는 하나님조차 그를 구원하지 않을 것이라고 단정합니다. 이 시의 중심 논지는 고난이 사라졌기 때문에 신뢰가 생긴다는 것이 아닙니다. 구원의 가능성 자체를 부정하는 말들이 들려오는 동안에도 기도자는 여호와를 자신의 방패와 영예로 부르고, 잠들고 깨어나는 일상적인 행위를 하나님의 붙드심 속에서 새롭게 해석합니다."],"centralMessage":"시의 움직임은 ‘많은 대적’과 ‘구원이 없다’는 말(1–2절), ‘그러나 주님은’이라는 반전과 응답의 확신(3–4절), 잠과 깨어남으로 드러나는 신뢰(5–6절), 하나님의 행동을 청하는 간구와 백성을 향한 축복(7–8절)으로 이어집니다. 다윗이 압살롬을 피해 달아날 때라는 표제는 이 기도를 왕실 반역의 이야기 속에서 읽도록 안내하지만, 시 자체는 특정 사건의 날짜나 군사적 승패를 보고하지 않습니다. 이 작품은 개인의 위기에서 출발하여 마지막에는 하나님의 백성 전체를 향해 시야를 넓힙니다.","literaryStructure":[{"v1":3,"v2":4,"title":"방패, 영광, 들려 올려지는 머리"},{"v1":5,"v2":6,"title":"잠들고 깨어나는 행위가 말하는 것"},{"v1":7,"v2":8,"title":"‘일어나소서’와 악의 이빨을 꺾는 구원"}],"sections":[{"id":"psa3-3-4","v1":3,"v2":4,"title":"방패, 영광, 들려 올려지는 머리","paragraphs":["3절은 대적의 말에 대한 정면 반박을 긴 논증 대신 하나님을 부르는 호칭으로 제시합니다. ‘그러나 주님’에 해당하는 **וְאַתָּה יְהוָה**(베아타 아도나이)는 대적이 ‘그에게 구원이 없다’고 말한 뒤 시인의 시선을 다른 대상으로 돌립니다. 기도자는 여호와를 **מָגֵן**(마겐, 방패), 자신의 **כָּבוֹד**(카보드, 영광·영예), ‘나의 머리를 드시는 분’으로 부릅니다. 방패는 전쟁의 물건이지만, 이 비유는 기도자가 실제로 어떤 무기를 들고 싸웠는지 알려 주지 않습니다. 그의 안전을 군사적 장비보다 하나님과의 관계에서 찾는 고백입니다.","‘나의 영광’은 특히 중요합니다. 왕에게 영광은 사람들 앞의 명예와 지위에 연결됩니다. 압살롬 전승의 맥락에서는 공개적인 수치와 왕위 상실이 위협으로 다가옵니다. 시인이 하나님을 자신의 영광이라고 부를 때, 그는 잃어버린 명성을 스스로 회복할 수 있다고 주장하지 않습니다. 사람들의 인정이 무너져도 자신을 세우는 궁극적 근원이 하나님이라는 신학적 재배치를 행합니다. ‘머리를 드신다’는 표현도 용기를 되찾게 하신다는 뜻, 수치를 거두신다는 뜻, 왕적 지위를 회복시키신다는 뜻이 겹쳐 읽힐 수 있습니다. 표제의 다윗 이야기는 마지막 독법에 힘을 주지만, 시적 이미지 전체를 왕위 복귀라는 하나의 사건으로만 좁힐 필요는 없습니다.","4절에서 기도자는 자신의 목소리로 여호와께 부르짖었고, 하나님이 ‘그의 거룩한 산’에서 응답하셨다고 말합니다. 앞선 시편 2:6의 ‘거룩한 산 시온’과 연결하면, 왕권이 위협받는 지금도 여호와의 통치 중심이 무너지지 않았다는 역설이 선명해집니다. 하지만 시는 어떤 환청이나 직접 들린 음성의 세부를 보고하지 않습니다. 응답을 경험한 기도자의 신뢰 언어이며, 하나님이 어떻게 역사하셨는지를 세밀한 사건 기록으로 재구성할 근거는 부족합니다. 대적이 내린 ‘구원이 없다’는 판결과, 기도자가 기억하는 ‘그가 응답하셨다’는 고백이 서로 맞섭니다."]},{"id":"psa3-5-6","v1":5,"v2":6,"title":"잠들고 깨어나는 행위가 말하는 것","paragraphs":["5절의 중심에는 뜻밖에도 전투가 아니라 수면이 있습니다. 기도자는 눕고 잠들었다가 다시 깨어났다고 말합니다. 히브리어 동사들은 그가 실제로 겪은 밤을 회상하는 듯 들리지만, 시의 신뢰를 반복적인 삶의 패턴으로 표현한다고 읽을 여지도 있습니다. 어느 쪽이든 초점은 수면의 길이나 생리적 회복 자체가 아닙니다. 위험이 없어져서 잠들 수 있었던 것이 아니라, 여호와가 자신을 **붙드셨다**는 고백 때문에 잠과 깨어남을 달리 이해하게 되었다는 점입니다.","잠은 가장 무방비한 상태입니다. 사람이 잠들면 적의 움직임을 감시하거나 자기 운명을 통제할 수 없습니다. 시인은 이 무방비함을 자신의 강함을 과시하는 증거가 아니라 하나님의 보호를 고백하는 자리에 놓습니다. 잠에서 깨어나는 순간은 아직 전쟁이 끝났다는 증명이 아닙니다. 그날의 생명을 자신이 홀로 유지한 것이 아니라는 인식입니다. 여기서 시편 4편의 ‘평안히 눕고 자는’ 결말과 자연스러운 상호본문적 연결이 형성됩니다. 두 시가 반드시 처음부터 한 쌍으로 작곡되었다고 단정할 수는 없지만, 정경 배열 속에서 아침의 깨어남과 밤의 잠이 서로 응답하는 것은 분명합니다.","6절에서 시인은 ‘만만의 백성’이 사방에서 둘러싸도 두려워하지 않겠다고 합니다. 숫자 표현은 전장의 병력 통계를 전달하기보다 앞서 ‘많은’ 대적이 등장했던 과장법을 확대합니다. 두려움의 부재를 타고난 담력이나 현실을 보지 않는 낙관으로 해석하면, 시가 처음부터 얼마나 절박하게 부르짖었는지를 지워 버립니다. 시의 신뢰는 두려운 현실을 삭제하는 감정이 아니라, 그 현실의 마지막 판단권을 대적에게 내주지 않는 기도입니다."]},{"id":"psa3-7-8","v1":7,"v2":8,"title":"‘일어나소서’와 악의 이빨을 꺾는 구원","paragraphs":["7절의 ‘일어나소서’는 하나님이 문자적으로 누워 계셨다가 일어나야 한다는 뜻이 아닙니다. 고대의 전투·구원 언어에서 하나님이 행동하시기를 청하는 명령형 간구입니다. 흥미롭게도 1절에서는 대적들이 ‘일어나’ 기도자를 치고, 여기서는 기도자가 여호와께 ‘일어나소서’라고 부릅니다. 인간의 공격적 일어남에 맞서는 하나님의 구원 행위를 요청하는 시적 대응입니다. ‘나의 하나님, 나를 구원하소서’라는 간구는 앞서 적들이 부정했던 바로 그 **구원**을 다시 하나님의 손에 맡깁니다.","‘원수의 뺨을 치고 악인의 이를 꺾으셨다’는 표현은 현대 독자가 불편하게 느낄 수 있는 거친 이미지입니다. 뺨을 치는 행위는 모욕과 굴욕을 나타내고, 이빨을 부수는 장면은 사나운 짐승이 물어뜯는 공격 능력을 무력화하는 은유로 읽을 수 있습니다. 히브리어의 완료형은 이미 경험한 구원을 회상하는 어법으로 읽을 수도 있고, 하나님의 확실한 개입을 기도 가운데 앞당겨 고백하는 방식으로 읽을 수도 있습니다. 본문은 특정한 전투에서 어떤 병사가 누구를 가격했는지를 기록하지 않습니다. 폭력적 이미지를 희석할 필요는 없지만, 이 구절을 기도자 자신이 보복을 실행하라는 명령으로 바꾸어서는 안 됩니다. 시의 행동 주체는 끝까지 하나님이십니다.","마지막 8절에서 주어가 바뀝니다. ‘구원은 여호와께 있다’는 선언 뒤에 ‘주의 백성에게 복이 있기를’이라는 기원이 나옵니다. 시의 시작에서는 ‘나’를 둘러싼 대적이 압도적이었지만, 끝에서는 ‘주의 백성’이 기도의 지평이 됩니다. 왕적 배경을 가진 개인 탄식이 공동체의 복을 향해 열리는 구조입니다. 이 결말은 구원이 한 사람의 안전 회복에만 머무르지 않고, 여호와의 백성에게 주어지는 선한 통치와 보호의 문제임을 보여 줍니다. 마지막 셀라는 그 공동체적 고백을 열린 울림으로 남깁니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"시편 2편의 약속과 시편 3편의 위기","paragraphs":["시편 2편은 여호와가 시온에 세운 왕을 향한 열방의 반역을 말하지만, 바로 다음 시는 그 왕권의 현실이 적대와 도피와 잠 못 이룰 위기에 놓일 수 있음을 보여 줍니다. 정경의 배열은 ‘기름부음 받은 왕은 언제나 눈에 보이는 승리를 누린다’는 단순한 결론을 허용하지 않습니다. 왕권의 약속과 왕의 고난 사이의 간격을 그대로 들려주는 것입니다. 사무엘하 15–18장의 압살롬 이야기는 그 간격을 역사적 서사로 구체화합니다. 그러나 사무엘하의 모든 사건을 시편의 각 행과 일대일로 대응시키는 것은 과도합니다."]},{"title":"개인 탄식의 공동체적 끝맺음","paragraphs":["1–7절은 일인칭 기도와 대적의 발언이 지배하지만 8절은 ‘주의 백성’의 복으로 끝납니다. 이 전환은 시가 개인 심리의 기록에 그치지 않고 예배 공동체가 함께 부를 수 있는 기도라는 점을 설명합니다. 왕의 구원과 백성의 복은 연결되지만, 그 연결을 근거로 왕의 개인적 이해관계가 곧 백성 전체의 선이라는 정치적 동일시를 해서는 안 됩니다."]},{"title":"표제·셀라·본문비평의 범위","paragraphs":["히브리어 본문에서 표제가 3:1로 계산되는 점은 실제 절 번호의 차이이지, 본문에 한 절이 추가되거나 삭제되었다는 뜻이 아닙니다. 셀라의 기능에는 여러 가설이 있으나 확정적 번역이 어렵습니다. 이 시의 주된 해석상 갈림길은 확인되지 않은 원문 이문을 상상하는 데 있지 않고, ‘머리를 드심’의 의미, 완료형 구원 진술의 시간감, 뺨과 이빨 이미지의 성격을 어떻게 시 전체의 탄식과 신뢰 속에 놓는가에 있습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 시편 3:1–8 및 시편 3–7편 묶음 설명, 2022 자료 · CC BY-SA 4","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"unfoldingWord Translation Notes · unfoldingWord · 시편 3편 서론·표제·3:1–8, en_tn v91 · CC BY-SA 4","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료","공통 성경자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 3편, 기존 JudeBible 원어 자료 v2.2 (히브리어 3:1–9) · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 표제·어절·동사 표현을 직접 대조하고 한국어로 문맥을 해설했습니다. 원어 표시의 슬래시 분절은 로컬 표시 방식이며 새로운 원전 판본을 뜻하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 3편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 3편의 방패·영광·머리·구원 등의 어휘에 관한 로컬 한국어 뜻풀이 검토자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 어휘 기본 뜻과 한국어 현지화 검토자료를 확인하여 짧은 한국어 풀이로 표현했습니다. 이 확인만으로 앱의 바인딩 또는 배포 승인을 추정하지 않습니다.","개별 WORBS 연구자료\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 3:1–8 및 시편 3–7편 묶음 설명, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 다윗 표제와 왕권 위기, 방패·잠·구원 간구의 흐름을 참고하여 한국어로 재구성하고 본문 관찰을 확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 3편 서론·표제·3:1–8, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 셀라의 불확실성, 머리를 드는 이미지, 이빨을 꺾는 은유 등 번역상 논점을 참고해 한국어 산문 주석으로 재서술했습니다. unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.","연구 및 재서술 안내\n이 글은 시편 3편의 히브리어 본문과 기존 검증된 공통 원어 자료를 대조하고, 본문별 Tyndale Open Study Notes 및 unfoldingWord Translation Notes를 실제 열람하여 작성한 한국어 WORBS 연구 주석입니다. 공통 성경자료와 개별 본문 해설 참고자료의 역할을 구별했으며, 표제의 역사적 의미와 시적 이미지의 해석에서 확정할 수 없는 사항을 구분했습니다. 실제 참고·번역·재서술 관계는 위에 밝혔으나 원고 전체의 독립 또는 파생 저작물 해당 여부를 임의로 확정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC는 Public Domain입니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)의 저작권자 표시·변경 고지 및 해당 조건을 따릅니다. 한국어 개역한글 본문의 연속 인용은 포함하지 않았으며, 성경 번역본의 권리는 원어 자료의 라이선스와 별개입니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n\n공통 성경자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 3편, 기존 JudeBible 원어 자료 v2.2 (히브리어 3:1–9) · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 표제·어절·동사 표현을 직접 대조하고 한국어로 문맥을 해설했습니다. 원어 표시의 슬래시 분절은 로컬 표시 방식이며 새로운 원전 판본을 뜻하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 3편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 3편의 방패·영광·머리·구원 등의 어휘에 관한 로컬 한국어 뜻풀이 검토자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 어휘 기본 뜻과 한국어 현지화 검토자료를 확인하여 짧은 한국어 풀이로 표현했습니다. 이 확인만으로 앱의 바인딩 또는 배포 승인을 추정하지 않습니다.\n\n개별 WORBS 연구자료\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 3:1–8 및 시편 3–7편 묶음 설명, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 다윗 표제와 왕권 위기, 방패·잠·구원 간구의 흐름을 참고하여 한국어로 재구성하고 본문 관찰을 확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 3편 서론·표제·3:1–8, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: 셀라의 불확실성, 머리를 드는 이미지, 이빨을 꺾는 은유 등 번역상 논점을 참고해 한국어 산문 주석으로 재서술했습니다. unfoldingWord® 상표·로고를 이 원고의 명칭으로 사용하지 않습니다.\n\n연구 및 재서술 안내\n이 글은 시편 3편의 히브리어 본문과 기존 검증된 공통 원어 자료를 대조하고, 본문별 Tyndale Open Study Notes 및 unfoldingWord Translation Notes를 실제 열람하여 작성한 한국어 WORBS 연구 주석입니다. 공통 성경자료와 개별 본문 해설 참고자료의 역할을 구별했으며, 표제의 역사적 의미와 시적 이미지의 해석에서 확정할 수 없는 사항을 구분했습니다. 실제 참고·번역·재서술 관계는 위에 밝혔으나 원고 전체의 독립 또는 파생 저작물 해당 여부를 임의로 확정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC는 Public Domain입니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)의 저작권자 표시·변경 고지 및 해당 조건을 따릅니다. 한국어 개역한글 본문의 연속 인용은 포함하지 않았으며, 성경 번역본의 권리는 원어 자료의 라이선스와 별개입니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전 확정하지 않습니다."},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"PSA_004_001_008_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/PSA_004_001_008_WORBS_READER_DRAFT_20261018.md","sourceSha256":"4ee6b383414dec89ed1b98889d32356af166164850e804c8805a0fb55f3fa88e","passage":{"book":"psa","chapter":4,"v1":1,"v2":8,"ref":"시편 4:1–8"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"좁은 자리에서 평안한 잠으로: 얼굴의 빛을 구하는 기도","overview":["시편 4편은 곤경에서 하나님께 부르짖는 개인의 기도로 시작하지만, 기도자는 곧 자신을 둘러싼 사람들에게 말을 건네고 다시 공동체의 불안한 질문을 하나님 앞에 가져옵니다. 시의 끝에는 물질적 풍요보다 깊은 기쁨과 잠자리에 드는 사람의 평안이 놓입니다. 중심 논지는 불안한 현실에서 평안을 얻는 길이 현실을 외면하는 데 있지 않고, 거짓을 좇는 말과 격앙된 행동을 멈추고 하나님의 의로움과 얼굴의 빛을 신뢰하는 데 있다는 것입니다. 그러나 이 작품을 단순한 수면 위로문으로 축소하면, 그 안에 있는 명예의 위기, 공동체의 갈등, 제사와 신뢰, 번영과 복의 기준에 대한 논쟁이 사라집니다."],"centralMessage":"기도의 흐름은 응답을 구하는 호소(1절), 사람들의 헛된 추구를 향한 책망과 여호와의 구별하심(2–3절), 동요를 침묵과 의로운 제사로 바꾸라는 권고(4–5절), 누가 좋은 것을 보이겠느냐는 공동체의 물음과 하나님의 얼굴의 빛을 구하는 기도(6절), 기쁨과 평안의 결론(7–8절)으로 읽을 수 있습니다. 시편 3편이 대적에게 둘러싸여 잠들었다가 깨어나는 신뢰를 노래했다면, 시편 4편은 그 신뢰가 잠자리에 드는 순간 어떤 언어를 얻는지 보여 줍니다. 두 시의 관계는 정경적 독서에 유익하지만, 두 작품의 최초 작곡 상황이 같았다고 단정할 근거는 아닙니다.","literaryStructure":[{"v1":1,"v2":1,"title":"좁은 곳에서 넓혀 주신 하나님께"},{"v1":2,"v2":3,"title":"사람의 영광을 욕되게 하는 거짓과 구별하심"},{"v1":4,"v2":5,"title":"동요하되 죄짓지 말고, 잠자리에서 침묵하라"},{"v1":6,"v2":6,"title":"‘누가 좋은 것을 보이겠는가’와 얼굴의 빛"},{"v1":7,"v2":8,"title":"풍요보다 깊은 기쁨, 그리고 평안한 잠"}],"sections":[{"id":"psa4-1-1","v1":1,"v2":1,"title":"좁은 곳에서 넓혀 주신 하나님께","paragraphs":["시편의 첫 절은 ‘나의 의의 하나님’이라는 부름으로 시작합니다. 히브리어 **אֱלֹהֵי צִדְקִי**(엘로헤이 치드키)는 ‘나를 의롭다 인정해 주시는 하나님’, ‘나의 정당함을 밝혀 주시는 하나님’, 또는 ‘나의 의로우신 하나님’으로 이해될 수 있습니다. 기도자의 무죄 주장과 하나님의 공의로운 성품 가운데 어느 면이 앞서는지는 논의할 여지가 있지만, 뒤따르는 억울함과 구출의 호소는 하나님이 자신을 바르게 판단해 주실 분이라는 신뢰를 드러냅니다. 이 표현을 기도자가 스스로 아무 잘못도 없는 절대적 의인이라고 선언한 것으로 확대하는 것은 조심해야 합니다.","‘곤란 중에 나를 넓게 하셨다’는 구문은 히브리어 **בַּצָּר**(바차르, 좁은 곳·압박)와 **הִרְחַבְתָּ**(히르하브타, 넓혀 주셨다)의 공간적 대조를 사용합니다. 삶이 좁아진다는 것은 움직일 수 없고 빠져나갈 길이 없다는 체감입니다. 하나님이 넓혀 주신다는 말은 숨 쉴 자리를 주시고 위협의 압박을 풀어 주신다는 이미지입니다. 완료형의 과거 구원을 기억하며 현재의 응답을 요청한다고 읽을 수 있고, 기도 속에서 확신을 앞당겨 말한다고 해석할 여지도 있습니다. 어느 경우든 시는 어려움이 이미 완전히 종료되었다는 사건 보고보다, 과거의 하나님의 행위를 근거로 다시 은혜를 구하는 기도에 가깝습니다.","시인은 ‘내가 부를 때 응답하소서’와 ‘나를 불쌍히 여기고 기도를 들으소서’를 반복합니다. 같은 내용을 말하는 듯하지만, 반복은 한 번의 청원으로 끝나지 않는 긴박함을 드러냅니다. 하나님께 대한 신뢰는 요청이 필요 없는 평정이 아니라, 응답을 기다리는 중에도 하나님을 떠나지 않는 관계로 나타납니다. 이 구조는 뒤의 8절에서 찾아오는 평안을 감정의 급격한 전환이 아니라 기도 속에서 형성되는 결말로 이해하게 합니다."]},{"id":"psa4-2-3","v1":2,"v2":3,"title":"사람의 영광을 욕되게 하는 거짓과 구별하심","paragraphs":["2절에서 기도자의 청중이 하나님에서 사람들로 바뀝니다. **בְּנֵי אִישׁ**(베네 이쉬)는 직역하면 ‘사람의 아들들’이지만, 단순히 인류 일반을 부르는 말인지 사회적 지위가 있는 인물들을 겨냥하는지 논의됩니다. 이 구절에서 기도자가 자신의 명예를 훼손하는 사람들을 꾸짖는다는 점은 분명하지만, 그들이 반드시 왕실 고관들이라고 확정할 수는 없습니다. 시인은 그들이 ‘영광’을 ‘수치’로 바꾸고, ‘헛된 것’을 사랑하며 ‘거짓’을 찾는다고 말합니다. **כָּבוֹד**(카보드, 영광·영예)는 시편 3편에서 하나님이 기도자의 영광이셨다는 고백과 연결됩니다. 여기에서는 사람들 사이에서 명예가 공격받는 구체적 장면이 드러납니다.","‘헛됨’과 ‘거짓’은 단지 말실수가 아니라 마음의 방향을 묻는 언어입니다. 우상숭배나 정치적 거짓 선전과 연결하는 해석도 가능하지만, 이 절만으로 어떤 특정 우상이나 역사적 음모를 확인할 수는 없습니다. 문맥상 분명한 것은 상대방이 믿을 만한 것을 버리고 지속되지 못할 것을 좇고 있다는 시인의 판정입니다. 반복되는 ‘언제까지’라는 질문은 그들의 태도가 일시적 오해가 아니라 계속되는 선택임을 드러냅니다. 시편 1편의 두 길을 떠올리게 하는 지혜의 어법이 개인 탄식 안에 스며 있습니다.","3절은 적대자들의 판단에 맞서 여호와의 행위를 말합니다. **הִפְלָה**(히플라, 구별하셨다)와 **חָסִיד**(하시드, 신실한 자·경건한 자)의 결합은 하나님이 자신에게 속한 사람을 알아보시고 특별히 대하신다는 뜻입니다. ‘경건한 자’를 도덕적으로 결함이 없는 엘리트로 이해하기보다, 여호와의 언약적 신실하심에 응답하는 사람이라는 관계적 의미를 살펴야 합니다. ‘그를 위하여’의 지시 대상을 어떻게 이해하느냐에 따라 번역의 결이 달라질 수 있지만, 기도자의 주장은 흔들리지 않습니다. 사람들은 명예를 수치로 바꾸려 하지만 여호와는 부르짖는 자를 외면하지 않으십니다."]},{"id":"psa4-4-5","v1":4,"v2":5,"title":"동요하되 죄짓지 말고, 잠자리에서 침묵하라","paragraphs":["4절의 **רִגְזוּ**(리그주)는 이 시에서 가장 중요한 번역 갈림길 가운데 하나입니다. 히브리어 어근은 흔들리다, 떨다, 격동하다, 분노하다의 의미 범위를 가지며, ‘두려워 떨라’와 ‘분을 내되 죄짓지 말라’는 독법이 모두 제시됩니다. 고대 그리스어 번역은 ‘분노하되 죄짓지 말라’는 방향으로 이해되었고, 에베소서 4:26은 그 표현을 다시 사용합니다. 그렇다고 신약의 인용을 근거로 히브리어 본문의 의미가 오직 분노뿐이었다고 소급해 확정할 수는 없습니다. 시의 흐름에서는 격앙된 감정이 어떻게 다루어져야 하는가가 중요합니다. 하나님을 경외하여 떨든 분노가 치밀어 오르든, 그 동요를 죄의 행동으로 옮기지 말라는 경계입니다.","이어지는 ‘너희 마음으로 말하고, 잠자리에서 잠잠하라’는 권고는 공개적 공격과 거짓말의 소음을 내면의 성찰과 침묵으로 바꿉니다. 여기서 ‘마음’은 단지 감정을 느끼는 자리가 아니라 판단하고 생각하고 결심하는 내면의 중심입니다. 침묵은 문제가 없다고 인정하라는 강요가 아닙니다. 자기 안의 격동을 곧바로 타인에 대한 폭력이나 험담으로 발산하지 말라는 요구입니다. ‘잠자리’는 시편 3편의 잠과 4편 끝의 평안한 수면을 이어 주는 이미지이기도 합니다. 4절에서 잠자리는 마음을 살피는 장소이고, 8절에서는 하나님이 안전을 주시는 장소가 됩니다.","5절의 ‘의로운 제사를 드리고 여호와를 의지하라’는 말은 내면의 침묵을 예배의 행위로 연결합니다. **זִבְחֵי־צֶדֶק**(지브헤 체데크, 의의 제사)는 정해진 의식 자체만으로 하나님을 움직이려는 태도와 거리가 있습니다. 합당한 제사와 여호와를 신뢰하는 마음이 나란히 요구됩니다. 이를 ‘제사는 필요 없고 마음만 있으면 된다’는 반의례적 선언으로 읽어도 지나치고, ‘제사를 바치면 곧바로 원하는 결과를 얻는다’는 거래적 이해로 읽어도 지나칩니다. 시인은 거짓을 좇는 관계를 떠나 하나님께 합당하게 응답하는 삶을 요청합니다."]},{"id":"psa4-6-6","v1":6,"v2":6,"title":"‘누가 좋은 것을 보이겠는가’와 얼굴의 빛","paragraphs":["6절에서 다시 ‘많은 사람들’의 목소리가 들립니다. 그들은 ‘누가 우리에게 좋은 것을 보여 주겠는가’라고 묻습니다. 이는 공동체의 절망적 푸념으로도, 현실적 복을 찾는 불안한 요구로도 들립니다. 시인은 그 질문을 단순히 비웃지 않고, 하나님을 향해 ‘주의 얼굴의 빛을 우리 위에 비추소서’라고 기도합니다. 원문의 ‘빛’과 ‘얼굴’의 결합은 하나님의 호의와 임재를 공간적·시각적으로 표현합니다. 하나님이 실제로 물리적 빛줄기를 비추어야만 이 기도가 응답되는 것은 아닙니다.","이 언어는 민수기 6:24–26의 제사장적 축복과 깊이 연결됩니다. ‘여호와께서 얼굴을 비추시고 은혜를 베푸신다’는 축복은 하나님이 백성을 외면하지 않고 그들에게 선을 베푸신다는 관계의 언어입니다. 시편 4편에서는 그 복을 묻는 질문이 시장의 성공이나 정치적 안정에 대한 답을 기다리다가, 하나님이 얼굴을 돌리시는지의 문제로 옮겨 갑니다. 그렇다고 곡식과 포도주의 실제 필요가 무가치하다는 뜻은 아닙니다. 좋은 것의 근원을 어디에서 찾는가가 논점입니다.","히브리어 **נְסָה**(네사, ‘들어 올리소서/비추소서’로 옮겨지는 청원)는 이 구절에서 형태와 표현을 어떻게 이해할지 논의되는 어휘입니다. 본문에 있는 표현을 매끈한 한국어로만 바꾸면 원문이 가진 낯섦이 사라질 수 있습니다. 그러나 번역상의 어려움을 곧바로 원문 자체가 잘못 전해졌다는 확정적 본문비평 판정으로 연결해서도 안 됩니다. 민수기의 축복과 시편 내부의 빛 이미지가 함께 이 청원의 의미 범위를 밝혀 줍니다."]},{"id":"psa4-7-8","v1":7,"v2":8,"title":"풍요보다 깊은 기쁨, 그리고 평안한 잠","paragraphs":["7절은 ‘마음에 기쁨을 주셨다’는 진술을 곡식과 새 포도주가 많아지는 때의 즐거움과 나란히 놓습니다. 곡식과 포도주는 고대 농경 사회에서 생존과 축제의 풍요를 가리키는 대표적 이미지입니다. 시인은 물질적 풍요를 악하다고 말하지 않습니다. 그 풍요가 가져오는 기쁨과 견주어도 하나님이 주시는 기쁨의 차원이 다르다고 말합니다. 히브리어 **מֵעֵת**(메에트)의 비교·시간 관계를 어떻게 옮기느냐에 따라 ‘그들의 곡식과 포도주가 많을 때보다 더 큰 기쁨’ 또는 ‘그들의 풍요가 늘어나는 때에 주신 기쁨’처럼 문장의 뉘앙스가 달라질 수 있습니다. 시 전체의 대조 구조를 보면 보이는 풍요만으로 하나님의 호의를 측정하지 않는다는 뜻이 중요합니다.","이 대목은 앞서 ‘누가 좋은 것을 보이겠는가’라고 묻던 사람들의 말에 대한 시인의 답이기도 합니다. 공동체는 좋은 것을 보려고 밖을 향해 질문했지만, 시인은 하나님이 자신의 마음에 기쁨을 주셨다고 말합니다. 외부 현실과 내적 기쁨을 완전히 분리하지 않으면서도, 외부 상황이 하나님과의 관계를 대신할 수 없다는 가치의 순서를 제시합니다. 이러한 기쁨은 감정 조절 기술의 성취가 아니라 ‘주께서 주셨다’는 수혜적 고백입니다.","8절의 ‘평안히 눕고 잠들겠다’는 결말은 1절의 압박과 정면으로 대조됩니다. **שָׁלוֹם**(샬롬, 평안)은 소음이 없다는 심리 상태를 넘어 안전과 온전함의 관계를 나타내고, **לָבֶטַח**(라베타흐, 안전하게)는 여호와께 대한 신뢰와 연결됩니다. 마지막 구문의 **לְבָדָד**(레바다드, 홀로/따로)는 ‘여호와께서 홀로 안전을 주신다’는 배타적 신뢰로 읽을 수도 있고, ‘홀로 떨어져 있어도 안전하게 살게 하신다’는 상태로 이해할 수도 있습니다. 어느 쪽이든 안전의 근거는 기도자의 힘이 아니라 여호와입니다. 시의 결말은 전쟁이 모두 끝나고 적들이 사라졌다는 보고가 아닙니다. 불확실한 밤을 맞는 사람이 자신을 붙드시는 분을 신뢰하며 눕는 장면입니다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"시편 3편과 4편의 밤과 아침","paragraphs":["시편 3편에서 기도자는 잠들었다가 깨어난 사실을 여호와의 붙드심으로 고백합니다. 시편 4편에서는 이제 잠들기 전에 자기 마음을 살피고, 공동체의 불안한 질문을 하나님의 얼굴의 빛으로 돌리며, 평안히 눕습니다. 두 시는 함께 읽을 때 기도의 시간적 리듬을 형성합니다. 다만 이 연결을 근거로 두 시가 역사적으로 같은 날 아침과 저녁에 작성되었다고 단정해서는 안 됩니다. 정경적 배치는 그러한 독서를 가능하게 하지만 최초 집필 상황을 확정해 주지는 않습니다."]},{"title":"‘분노하되 죄짓지 말라’의 해석 경계","paragraphs":["시편 4:4의 히브리어는 ‘떨다/동요하다/분노하다’의 의미 영역을 지니며, 고대 그리스어 번역과 에베소서 4:26은 그중 분노의 독법을 두드러지게 합니다. 신약의 사용은 정경적 상호본문성을 보여 주지만, 고대 번역이 원문의 모든 가능성을 소진했다는 뜻은 아닙니다. 중요한 것은 감정이 치솟는 순간에도 그것이 죄의 말과 행동으로 굳어지지 않도록 내면의 판단과 침묵, 하나님을 향한 신뢰가 요청된다는 점입니다. 이 권고를 억압받는 사람이 침묵해야 한다는 사회적 명령으로 전용하는 것은 시가 겨냥한 거짓과 악행의 책임을 흐립니다."]},{"title":"본문비평과 경쟁 해석을 구별하기","paragraphs":["이 시에서 1절 ‘나의 의의 하나님’, 2절 ‘사람의 아들들’, 4절 ‘떨라/분노하라’, 6절 ‘얼굴의 빛을 들어 올리소서’, 7절의 비교 구문, 8절 ‘홀로’는 번역과 구문 해석의 중요한 갈림길입니다. 이 가운데 특히 4절의 고대 그리스어 독법은 번역 전승의 비교 문제를 제기합니다. 그러나 서로 다른 번역이 존재한다는 사실만으로 마소라 본문에 특정한 필사 오류가 있다고 주장할 수는 없습니다. 독자는 확인된 히브리어 형태와 고대 번역의 해석, 현대 번역의 선택을 구분해야 합니다."]},{"title":"민수기의 축복과 시편의 ‘좋은 것’","paragraphs":["민수기 6장의 제사장 축복은 하나님이 얼굴을 비추시는 일을 은혜와 평강의 언어로 말합니다. 시편 4편은 같은 축복의 언어를 공동체의 불안한 질문에 응답하는 기도로 사용합니다. 곡식과 포도주의 풍요는 선물이지만 하나님 자신의 호의와 동일하지 않습니다. 이 긴장은 시편 1편의 ‘형통’이나 시편 73편의 ‘악인의 형통’을 읽을 때도 유익합니다. 시편의 복은 즉각적인 경제적 결과와 일대일로 환산되지 않습니다."]}],"relatedResearch":[],"readerSources":[{"name":"Tyndale Open Study Notes","locator":"Tyndale Open Study Notes · Tyndale House Publishers · 시편 4:1–8, 2022 자료 · CC BY-SA 4","license":"CC BY-SA 4.0"},{"name":"unfoldingWord Translation Notes","edition":"v91","locator":"unfoldingWord Translation Notes · unfoldingWord · 시편 4편 서론·표제·4:1–8, en_tn v91 · CC BY-SA 4","license":"CC BY-SA 4.0"}],"notes":["연구 참고자료","공통 성경자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 4편, 기존 JudeBible 원어 자료 v2.2 (히브리어 4:1–9) · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 표제·어절·시적 구문을 직접 대조하여 한국어로 해설했습니다. 로컬 어절 분절을 원전의 판본 변경으로 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 4편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 4편의 동요·영광·평안 등 어휘에 관한 로컬 한국어 뜻풀이 검토자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 기본 뜻과 한국어 현지화 검토자료를 참고하여 문맥에 맞는 짧은 한국어 풀이를 작성했습니다. 이 사실만으로 앱 바인딩이나 배포 승인을 추정하지 않습니다.","개별 WORBS 연구자료\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 4:1–8, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 시의 구조, 기도와 적대자 책망, 제사·분노·하나님의 얼굴의 빛·평안의 흐름을 참고해 한국어로 재구성하고 원어 및 정경적 관찰을 확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 4편 서론·표제·4:1–8, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: ‘나의 의의 하나님’, ‘사람의 아들들’, 동요/분노의 독법, 마음·침묵·잠자리의 시적 반복, 평안의 구문을 검토하여 한국어 산문으로 재서술했습니다. unfoldingWord® 상표·로고를 원고의 명칭으로 사용하지 않습니다.","연구 및 재서술 안내\n이 글은 시편 4편의 히브리어 본문을 직접 대조하고, 위에 적은 공통 성경자료와 본문별 Tyndale Open Study Notes 및 unfoldingWord Translation Notes를 실제 확인하여 작성한 한국어 WORBS 연구 주석입니다. 시적 구조와 본문의 화자 변화, 번역상 갈림길, 민수기 및 에베소서와의 상호본문성을 중심으로 재구성했습니다. 공통 원어 자료와 개별 연구 주석의 역할을 구분했으며, 실제 참고·번역·재서술 관계는 표시하되 원고 전체의 독립 또는 파생 저작물 여부를 임의로 단정하지 않습니다.","라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC는 Public Domain입니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)의 저작권자 표시·변경 고지 및 해당 조건을 따릅니다. 한국어 개역한글 본문의 연속 인용은 포함하지 않았으며, 성경 번역본의 권리는 원어 자료의 라이선스와 별개입니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전 확정하지 않습니다."],"sourceNotice":"연구 참고자료\n\n공통 성경자료\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · 시편 4편, 기존 JudeBible 원어 자료 v2.2 (히브리어 4:1–9) · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/morphhb\n   * 변경·번역 고지: 히브리어 표제·어절·시적 구문을 직접 대조하여 한국어로 해설했습니다. 로컬 어절 분절을 원전의 판본 변경으로 주장하지 않습니다.\n* Westminster Leningrad Codex (WLC) · Westminster Hebrew Institute / OSHB의 기반 히브리어 본문 · 시편 4편 기반 본문 · Public Domain\n   * 기반 판본 식별: https://github.com/openscriptures/morphhb\n* Open Scriptures Hebrew Lexicon · Open Scriptures Hebrew Bible Project · 시편 4편의 동요·영광·평안 등 어휘에 관한 로컬 한국어 뜻풀이 검토자료 · CC BY 4.0\n   * 원자료: https://github.com/openscriptures/HebrewLexicon\n   * 변경·번역 고지: 영어 기본 뜻과 한국어 현지화 검토자료를 참고하여 문맥에 맞는 짧은 한국어 풀이를 작성했습니다. 이 사실만으로 앱 바인딩이나 배포 승인을 추정하지 않습니다.\n\n개별 WORBS 연구자료\n* Tyndale Open Study Notes · Tyndale House Publishers · 시편 4:1–8, 2022 자료 · CC BY-SA 4.0, Copyright © 2022 Tyndale House Publishers\n   * 원자료: http://www.tyndaleopenresources.com\n   * 저작권자 지정 고지: Adapted from Tyndale Open Study Notes. The original work by Tyndale House Publishers is available for free at http://www.tyndaleopenresources.com.\n   * 변경·번역 고지: 시의 구조, 기도와 적대자 책망, 제사·분노·하나님의 얼굴의 빛·평안의 흐름을 참고해 한국어로 재구성하고 원어 및 정경적 관찰을 확장했습니다.\n* unfoldingWord Translation Notes · unfoldingWord · 시편 4편 서론·표제·4:1–8, en_tn v91 · CC BY-SA 4.0, Copyright © 2022 unfoldingWord\n   * 원자료: https://git.door43.org/unfoldingWord/en_tn/releases/tag/v91\n   * 저작권자 지정 고지: The original work by unfoldingWord is available from https://www.unfoldingword.org/utn\n   * 변경·번역 고지: ‘나의 의의 하나님’, ‘사람의 아들들’, 동요/분노의 독법, 마음·침묵·잠자리의 시적 반복, 평안의 구문을 검토하여 한국어 산문으로 재서술했습니다. unfoldingWord® 상표·로고를 원고의 명칭으로 사용하지 않습니다.\n\n연구 및 재서술 안내\n이 글은 시편 4편의 히브리어 본문을 직접 대조하고, 위에 적은 공통 성경자료와 본문별 Tyndale Open Study Notes 및 unfoldingWord Translation Notes를 실제 확인하여 작성한 한국어 WORBS 연구 주석입니다. 시적 구조와 본문의 화자 변화, 번역상 갈림길, 민수기 및 에베소서와의 상호본문성을 중심으로 재구성했습니다. 공통 원어 자료와 개별 연구 주석의 역할을 구분했으며, 실제 참고·번역·재서술 관계는 표시하되 원고 전체의 독립 또는 파생 저작물 여부를 임의로 단정하지 않습니다.\n\n라이선스\nOSHB와 Open Scriptures Hebrew Lexicon은 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)으로 확인되며, 기반 WLC는 Public Domain입니다. Tyndale Open Study Notes와 unfoldingWord Translation Notes는 각각 CC BY-SA 4.0(https://creativecommons.org/licenses/by-sa/4.0/)의 저작권자 표시·변경 고지 및 해당 조건을 따릅니다. 한국어 개역한글 본문의 연속 인용은 포함하지 않았으며, 성경 번역본의 권리는 원어 자료의 라이선스와 별개입니다. 이 원고 전체의 단일 라이선스는 별도 권리 검토 전 확정하지 않습니다."}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("psa");})(window);
